mapper.select:
SELECT COUNT(*) FROM market_tbl WHERE market_status = #{status}
AND market_title LIKE CONCAT('%', #{searchKeyword}, '%')
AND market_writer = #{searchKeyword}
AND ( #{location} = 0 OR sell_addr LIKE CONCAT('%', CASE #{location} WHEN 1 THEN '서울' WHEN 2 THEN '강원' WHEN 3 THEN '경기' WHEN 4 THEN '경남' WHEN 5 THEN '경북' WHEN 6 THEN '광주' WHEN 7 THEN '대구' WHEN 8 THEN '대전' WHEN 9 THEN '부산' WHEN 10 THEN '세종' WHEN 11 THEN '울산' WHEN 12 THEN '인천' WHEN 13 THEN '전남' WHEN 14 THEN '전북' WHEN 15 THEN '제주' WHEN 16 THEN '충남' WHEN 17 THEN '충북' END, '%') )
AND completed = 0

mapper.update:
UPDATE market_tbl SET
market_title = #{marketTitle},
market_content = #{marketContent},
sell_addr = #{sellAddr},
sell_price = #{sellPrice}
WHERE market_no = #{marketNo}

mapper.insert:
INSERT INTO trade_request_tbl (
	market_no, buyer_id, message, status, request_date, complete_date
) VALUES (
	#{marketNo}, #{buyerId}, #{message}, 1, NOW(), NULL
)

mapper.select:
SELECT COUNT(*) FROM score_history_tbl WHERE member_id = #{memberId}
AND history_status = 1
AND history_status = 2

SELECT score_no, history_status, member_id, market_no, CASE WHEN s.market_no IS NULL THEN '닉네임 변경' ELSE (SELECT m.market_title FROM market_tbl m WHERE m.market_no = s.market_no) END AS market_title, changed_score, score_date FROM score_history_tbl s WHERE member_id = #{memberId}
AND history_status = 1
AND history_status = 2
ORDER BY score_date DESC ORDER BY score_date ASC LIMIT #{request.size} OFFSET ${request.page*request.size}

mapper.update:
UPDATE member_tbl SET
member_score = member_score + 100
WHERE member_id = #{sellerId}

UPDATE member_tbl SET
member_score = member_score + 100
WHERE member_id = #{buyerId}
